using System;using System.Linq;using Exoduser.UnityPort;using Exoduser.UnityPort.Core;
class ArenaTests {static int checks,bad;static void Check(bool ok,string label){checks++;if(!ok){bad++;Console.WriteLine("FAIL "+label);}}static int Main(){var a=BossArenaLayout.Generate(0);var before=(int[])a.Tiles.Clone();var mesh=NativeArena3DPlan.Build(a);Check(a.Tiles.SequenceEqual(before),"presentation cannot change collision tiles");Check(mesh.TopCells==(BossArenaLayout.Width+2*NativeArena3DPlan.Margin)*(BossArenaLayout.Height+2*NativeArena3DPlan.Margin),"top coverage includes entire viewport overscan");Check(mesh.FloorCells==a.Tiles.Count(x=>x!=1),"one flat quad for every walkable tile");Check(mesh.WallCells>0&&mesh.MinWallHeight>=3&&mesh.MaxWallHeight<=6,"outer mass height 3..6");Check(mesh.Vertices.All(v=>!float.IsNaN(v.X)&&!float.IsNaN(v.Y)&&!float.IsNaN(v.Z)),"finite geometry");Check(mesh.Triangles.All(i=>i>=0&&i<mesh.Vertices.Count),"valid indexed mesh");bool up=true;for(int i=0;i<mesh.Triangles.Count;i+=3){var v0=mesh.Vertices[mesh.Triangles[i]];var v1=mesh.Vertices[mesh.Triangles[i+1]];var v2=mesh.Vertices[mesh.Triangles[i+2]];float ny=(v1.Z-v0.Z)*(v2.X-v0.X)-(v1.X-v0.X)*(v2.Z-v0.Z);if(ny<-.00001)up=false;}Check(up,"top triangles face upward");int at=a.ExitY*BossArenaLayout.Width+a.ExitX;int old=a.Tiles[at];a.Tiles[at]=0;var opened=NativeArena3DPlan.Build(a);Check(opened.FloorCells==mesh.FloorCells+(old==1?1:0),"opening exit replaces wall with floor");var camera=new NativeArena3DCameraState();Check(Math.Abs(camera.Distance-16.5f)<.0001,"field distance untouched initially");camera.Step(true,.3f);Check(Math.Abs(camera.Distance-17.4f)<.0001,"halfway continuous zoom");camera.Step(true,.3f);Check(Math.Abs(camera.Distance-18.3f)<.0001,"settles at 18.3 in 0.6sec");camera.Step(false,0);Check(Math.Abs(camera.Distance-18.3f)<.0001,"exit target change cannot jump pose");camera.Step(false,.6f);Check(Math.Abs(camera.Distance-16.5f)<.0001,"exit restores field distance");Console.WriteLine("boss-arena-plan checks="+checks+" failed="+bad);return bad>0?1:0;}}
